package com.project.web.controller.system;
import java.util.*;import java.nio.charset.StandardCharsets;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import com.project.system.service.*;import com.fasterxml.jackson.databind.ObjectMapper;
@Controller @RequestMapping("/api/v1/merchant") public class MerchantGatewayController{
 @Autowired private MerchantApiService service;private final ObjectMapper json=new ObjectMapper();
 @PostMapping(value="/{action}",consumes="application/json",produces="application/json;charset=UTF-8") @ResponseBody
 public ResponseEntity<String> request(@PathVariable String action,@RequestBody byte[] bytes,@RequestHeader(value="X-Merchant-Id",required=false)String id,@RequestHeader(value="X-Timestamp",required=false)String time,@RequestHeader(value="X-Nonce",required=false)String nonce,@RequestHeader(value="X-Signature",required=false)String signature){return dispatch(action,new String(bytes,StandardCharsets.UTF_8),id,time,nonce,signature);}
 public ResponseEntity<String> dispatch(String action,String body,String id,String time,String nonce,String signature){String trace=UUID.randomUUID().toString(),order=null;Map<String,Object> credential=null;Map<String,Object> response=new LinkedHashMap<>();HttpStatus status=HttpStatus.OK;String code="SUCCESS",message="请求处理成功";Object data=null;
 try{if(!Arrays.asList("balance","pay","recharge","query").contains(action))throw new IllegalArgumentException("不支持的接口操作");if(body.getBytes(StandardCharsets.UTF_8).length>16384)throw new IllegalArgumentException("请求体超过16KB");credential=service.authenticate(id,time,nonce,signature,"/api/v1/merchant/"+action,body);Map<String,String> payload=service.parse(body,action);order=payload.get("campusOrderNo");Map<String,Object> result=action.equals("balance")?service.balance(credential,payload):action.equals("query")?service.paymentQuery(credential,payload):service.payment(credential,payload,action.equals("pay")?"PAY":"RECHARGE");data=result;order=(String)result.get("campusOrderNo");if("FAILED".equals(result.get("status"))){status=HttpStatus.UNPROCESSABLE_ENTITY;code="TRADE_FAILED";message=String.valueOf(result.get("message"));}}
 catch(IllegalArgumentException e){status=credential==null?HttpStatus.UNAUTHORIZED:HttpStatus.BAD_REQUEST;code=credential==null?"AUTH_FAILED":"INVALID_REQUEST";message=e.getMessage();}catch(Exception e){status=HttpStatus.INTERNAL_SERVER_ERROR;code="SYSTEM_ERROR";message="系统处理异常，请通过原订单查询结果，避免更换订单重复交易";}
 response.put("code",code);response.put("message",message);response.put("traceId",trace);response.put("data",data);service.log(trace,id,order,action,code,message);try{String raw=json.writeValueAsString(response);HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.parseMediaType("application/json;charset=UTF-8"));headers.set("Cache-Control","no-store");if(credential!=null){String t=String.valueOf(java.time.Instant.now().getEpochSecond()),n=UUID.randomUUID().toString();headers.set("X-Timestamp",t);headers.set("X-Nonce",n);headers.set("X-Signature",ApiSecurity.sign((String)credential.get("secret"),t,n,"/api/v1/merchant/"+action,raw));}return new ResponseEntity<>(raw,headers,status);}catch(Exception e){throw new IllegalStateException(e);}}
}
